#include "PluginEditor.h"
using namespace juce;
SoundImagerEditor::SoundImagerEditor(SoundImagerProcessor& p):AudioProcessorEditor(p),processor(p) {
 theme.setColour(Slider::rotarySliderFillColourId,Colour(0xff49e0c1));
 theme.setColour(Slider::rotarySliderOutlineColourId,Colour(0xff293b49));
 theme.setColour(Slider::textBoxTextColourId,Colours::white);theme.setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);
 theme.setColour(ToggleButton::textColourId,Colours::white);theme.setColour(ToggleButton::tickColourId,Colour(0xff49e0c1));setLookAndFeel(&theme);
 const char* ids[]={"width","rotation","asymmetry","balance","bass","gain"};
 const char* names[]={"WIDTH  %","ROTATION  deg","ASYMMETRY  dB","BALANCE  %","MONO BASS  Hz","OUTPUT  dB"};
 for(size_t i=0;i<6;++i){auto& k=knobs[i];k.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);k.setTextBoxStyle(Slider::TextBoxBelow,false,100,24);addAndMakeVisible(k);labels[i].setText(names[i],dontSendNotification);labels[i].setJustificationType(Justification::centred);labels[i].setColour(Label::textColourId,Colour(0xffa3b9c8));addAndMakeVisible(labels[i]);attachments[i]=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],k);k.setDoubleClickReturnValue(true,p.state.getParameter(ids[i])->convertFrom0to1(p.state.getParameter(ids[i])->getDefaultValue()));}
 const char* bIDs[]={"mono","swap","bypass"}; const char* bNames[]={"Mono","Swap L / R","Bypass"};
 for(size_t i=0;i<3;++i){buttons[i].setButtonText(bNames[i]);addAndMakeVisible(buttons[i]);buttonAttachments[i]=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,bIDs[i],buttons[i]);}
 addAndMakeVisible(reset);reset.onClick=[this]{for(auto* param:processor.getParameters()){param->beginChangeGesture();param->setValueNotifyingHost(param->getDefaultValue());param->endChangeGesture();}};
 setSize(880,580);setResizable(true,true);setResizeLimits(880,580,1320,870);startTimerHz(30);
}
SoundImagerEditor::~SoundImagerEditor(){stopTimer();setLookAndFeel(nullptr);}
void SoundImagerEditor::resized(){const float sx=getWidth()/880.0f,sy=getHeight()/580.0f;for(size_t i=0;i<6;++i){int col=int(i%3),row=int(i/3);labels[i].setBounds(int((450+col*134)*sx),int((100+row*180)*sy),int(128*sx),int(24*sy));knobs[i].setBounds(int((450+col*134)*sx),int((126+row*180)*sy),int(128*sx),int(140*sy));}for(int i=0;i<3;++i)buttons[size_t(i)].setBounds(int((40+i*145)*sx),int(525*sy),int(140*sx),int(30*sy));reset.setBounds(int(735*sx),int(525*sy),int(105*sx),int(30*sy));}
void SoundImagerEditor::timerCallback(){int a,n,c,k;processor.scopeFifo.prepareToRead(processor.scopeFifo.getNumReady(),a,n,c,k);for(int i=0;i<n;++i)points[size_t(head++%512)]=processor.scope[size_t(a+i)];for(int i=0;i<k;++i)points[size_t(head++%512)]=processor.scope[size_t(c+i)];processor.scopeFifo.finishedRead(n+k);head%=512;repaint();}
void SoundImagerEditor::paint(Graphics& g){g.fillAll(Colour(0xff101922));g.addTransform(AffineTransform::scale(getWidth()/880.0f,getHeight()/580.0f));g.setColour(Colours::white);g.setFont(30);g.drawText("SOUND IMAGER",36,24,450,40,Justification::centredLeft);g.setColour(Colour(0xff49e0c1));g.setFont(13);g.drawText("MALLULA AUDIO     /     STEREO FIELD PROCESSOR",38,66,650,22,Justification::centredLeft);
 g.setColour(Colour(0xff182732));g.fillRoundedRectangle(32,104,392,345,14);g.setColour(Colour(0xff304554));for(int r=45;r<=135;r+=45)g.drawEllipse(228.0f-r,273.0f-r,2.0f*r,2.0f*r,1);g.drawLine(78,273,378,273);g.drawLine(228,123,228,423);g.drawLine(122,167,334,379);g.drawLine(122,379,334,167);g.setFont(12);g.setColour(Colour(0xffa3b9c8));g.drawText("L",110,143,30,20,Justification::centred);g.drawText("R",318,143,30,20,Justification::centred);g.drawText("MONO",198,108,60,20,Justification::centred);
 g.saveState();g.reduceClipRegion(40,128,375,305);g.setColour(Colour(0xff49e0c1).withAlpha(0.5f));for(auto v:points){float x=228+std::tanh((v.x-v.y)*0.7f)*175,y=273-std::tanh((v.x+v.y)*0.7f)*155;g.fillEllipse(x,y,2.5f,2.5f);}g.restoreState();
 float corr=processor.correlation.load();g.setFont(14);g.setColour(Colours::white);g.drawText("CORRELATION  "+String(corr,2),38,459,380,24,Justification::centredLeft);g.setColour(Colour(0xff304554));g.fillRoundedRectangle(38,491,380,7,3);g.setColour(corr<0?Colour(0xffffa46a):Colour(0xff49e0c1));g.fillEllipse(38+(corr+1)*0.5f*372,488,12,13);
 g.setFont(13);auto db=[](float v){return v<0.00001f?String("-inf"):String(Decibels::gainToDecibels(v),1);};float l=processor.peakL.load(),r=processor.peakR.load();g.setColour(std::max(l,r)>1?Colour(0xffff866a):Colour(0xffa3b9c8));g.drawText("PEAK  L "+db(l)+"    R "+db(r)+" dBFS",450,466,395,28,Justification::centred);}
